from typing import ClassVar, List, Union, Optional

from dlt.common.typing import TSecretStrValue
from dlt.common.configuration.specs.base_configuration import CredentialsConfiguration, configspec


@configspec
class OAuth2Credentials(CredentialsConfiguration):
    client_id: str = None
    client_secret: TSecretStrValue = None
    refresh_token: Optional[TSecretStrValue] = None
    scopes: Optional[List[str]] = None

    token: Optional[TSecretStrValue] = None
    """Access token"""

    # add refresh_token when generating config samples
    __config_gen_annotations__: ClassVar[List[str]] = ["refresh_token"]

    def auth(self, scopes: Union[str, List[str]] = None, redirect_url: str = None) -> None:
        """Authorizes the client using the available credentials

        Uses the `refresh_token` grant if refresh token is available. Note that `scopes` and `redirect_url` are ignored in this flow.
        Otherwise obtains refresh_token via web flow and authorization code grant.

        Sets `token` and `access_token` fields in the credentials on successful authorization.

        Args:
            scopes (Union[str, List[str]], optional): Additional scopes to add to configured scopes. To be used in web flow. Defaults to None.
            redirect_url (str, optional): Redirect url in case of web flow. Defaults to None.
        """
        raise NotImplementedError()

    def add_scopes(self, scopes: Union[str, List[str]]) -> None:
        if not self.scopes:
            if isinstance(scopes, str):
                self.scopes = [scopes]
            else:
                self.scopes = scopes
        else:
            if isinstance(scopes, str):
                if scopes not in self.scopes:
                    self.scopes += [scopes]
            elif scopes:
                self.scopes = list(set(self.scopes + scopes))

from base64 import b64encode
from typing import Any, Dict, cast

import pytest

from dlt.common.exceptions import ValueErrorWithKnownValues
from dlt.sources import rest_api
from dlt.sources.helpers.rest_client.auth import APIKeyAuth, OAuth2ClientCredentials
from dlt.sources.rest_api.typing import ApiKeyAuthConfig, AuthConfig, RESTAPIConfig


class CustomOAuth2(OAuth2ClientCredentials):
    def build_access_token_request(self) -> Dict[str, Any]:
        """Used e.g. by Zoom Zoom Video Communications, Inc."""
        authentication: str = b64encode(f"{self.client_id}:{self.client_secret}".encode()).decode()
        return {
            "headers": {
                "Authorization": f"Basic {authentication}",
                "Content-Type": "application/x-www-form-urlencoded",
            },
            "data": self.access_token_request_data,
        }


class TestCustomAuth:
    @pytest.fixture
    def custom_auth_config(self) -> AuthConfig:
        config: AuthConfig = {
            "type": "custom_oauth_2",  # type: ignore
            "access_token_url": "https://example.com/oauth/token",
            "client_id": "test_client_id",
            "client_secret": "test_client_secret",
            "access_token_request_data": {
                "grant_type": "account_credentials",
                "account_id": "test_account_id",
            },
        }
        return config

    def test_creates_builtin_auth_without_registering(self) -> None:
        config: ApiKeyAuthConfig = {
            "type": "api_key",
            "api_key": "test-secret",
            "location": "header",
        }
        auth = cast(APIKeyAuth, rest_api.config_setup.create_auth(config))
        assert auth.api_key == "test-secret"

    def test_not_registering_throws_error(self, custom_auth_config: AuthConfig) -> None:
        with pytest.raises(ValueErrorWithKnownValues) as e:
            rest_api.config_setup.create_auth(custom_auth_config)

        assert e.match("Received invalid value `auth_type=custom_oauth_2`. Valid values are:")

    def test_registering_adds_to_AUTH_MAP(self, custom_auth_config: AuthConfig) -> None:
        rest_api.config_setup.register_auth("custom_oauth_2", CustomOAuth2)
        cls = rest_api.config_setup.get_auth_class("custom_oauth_2")
        assert cls is CustomOAuth2

        # teardown test
        del rest_api.config_setup.AUTH_MAP["custom_oauth_2"]

    def test_registering_allows_usage(self, custom_auth_config: AuthConfig) -> None:
        rest_api.config_setup.register_auth("custom_oauth_2", CustomOAuth2)
        auth = cast(CustomOAuth2, rest_api.config_setup.create_auth(custom_auth_config))
        request = auth.build_access_token_request()
        assert request["data"]["account_id"] == "test_account_id"

        # teardown test
        del rest_api.config_setup.AUTH_MAP["custom_oauth_2"]

    def test_registering_not_auth_config_base_throws_error(self) -> None:
        class NotAuthConfigBase:
            pass

        with pytest.raises(ValueError) as e:
            rest_api.config_setup.register_auth(
                "not_an_auth_config_base", NotAuthConfigBase  # type: ignore
            )
        assert e.match("Invalid auth: `NotAuthConfigBase`.")

    def test_valid_config_raises_no_error(self, custom_auth_config: AuthConfig) -> None:
        rest_api.config_setup.register_auth("custom_oauth_2", CustomOAuth2)

        valid_config: RESTAPIConfig = {
            "client": {
                "base_url": "https://example.com",
                "auth": custom_auth_config,
            },
            "resources": ["test"],
        }

        rest_api.rest_api_source(valid_config)

        del rest_api.config_setup.AUTH_MAP["custom_oauth_2"]

